# Check that the R environment can read the ABC Atlas cloud data.
#
# Reads the gene table and a tiny slice of expression from the public WMB-10Xv3 store, the same way the
# scripts generated by the ABC Atlas do.
#
#   Rscript check_setup.R        (or, in the pixi environment:  pixi run check)

suppressPackageStartupMessages(library(arrow))
globalCallingHandlers(RarrZstdMissingWarning = function(w) invokeRestart("muffleWarning"))

bucket <- "abc-atlas-data-refactor"
prefix <- "refactor/WMB-10Xv3/20230630/WMB-10Xv3-log2"
t0 <- Sys.time()
gcs <- GcsFileSystem$create(anonymous = TRUE)  # public bucket: no credentials needed
var <- read_parquet(gcs$path(sprintf("%s/%s.var.parquet", bucket, prefix)), col_select = c("gene_index", "gene_symbol"))
gene <- var$gene_index[var$gene_symbol == "Slc17a7"] + 1
x <- Rarr::read_zarr_array(sprintf("https://storage.googleapis.com/%s/%s.zarr/X", bucket, prefix), index = list(1:1000, gene))
cat(sprintf("R %s, arrow %s, Rarr %s\n", getRversion(), packageVersion("arrow"), packageVersion("Rarr")))
cat(sprintf("read %s genes and X[1:1000, Slc17a7] (mean %.3f) from gs://%s in %.1fs\n",
            format(nrow(var), big.mark = ","), mean(x), bucket, as.numeric(Sys.time() - t0, units = "secs")))
cat("OK: the R environment can read the ABC Atlas cloud data\n")
